public int minCostClimbingStairs(int[] cost) {
    if (cost.length == 0) return 0;
    if (cost.length == 1) return cost[0];

    int n = cost.length;
    int[] dp = new int[n + 1];
    dp[1] = cost[0];
    dp[2] = cost[1];

    for (int i = 3; i <= n; i++) {
        dp[i] = Math.min(dp[i - 1], dp[i - 2]) + cost[i - 1];
    }

    return dp[n];
}

