        }
    }

    // Check for diagonal lines
    for (int i = 0; i < m; i++) {
        int currentLength = 0;
        for (int j = 0; j < n; j++) {
            if (i - j >= 0 && mat[i][j] == 1) {
                currentLength++;
            } else {
                currentLength = 0;
            }
            maxLength = Math.max(maxLength, currentLength);
        }
    }

    // Check for antidiagonal lines
    for (int i = 0; i < m; i++) {
        int currentLength = 0;
