              (points[2][0] - points[0][0]) * (points[1][1] - points[0][1]);

    // A boomerang should have a non-zero area
    return area != 0;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("The index must be a positive integer.");
    }

    Queue<Long> pq = new PriorityQueue<>();
    pq.offer(1L);
    Set<Long> seen = new HashSet<>();
    seen.add(1L);

    int[] uglyFactors = {2, 3, 5};
    int[] temp = new int[n];
    temp[0] = 1;
    for (int i = 1; i < n; i++) {
        long nextUgly = pq.poll();
        temp[i] = (int) nextUgly;

        for (int factor : uglyFactors) {
            long newUgly = nextUgly * factor;
            if (!seen.contains(newUgly)) {
                pq.offer(newUgly);
                seen.add(newUgly);
            }
        }
    }

    return temp[n - 1];
}

public static int calculateEnergy(String s) {
    if (s == null || s.length() < 1) {
        return 0;
    }

    int maxLen = 1;
    int currentLen = 1;

    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            currentLen++;
            maxLen = Math.max(maxLen, currentLen);
        } else {
            currentLen = 1;
        }
    }

    return maxLen;
}

public static List<Integer> lexicalOrder(int n) {
        List<Integer> result = new ArrayList<>();
        if (n <= 0) {
            return result;
        }
        for (int i = 1; i <= 9; i++) {
            result.add(i);
            if (i == n) {
                return result;
            }
        }
        for (int i = 10; i <= n; i *= 10) {
            for (int j = 0; j < 10; j++) {
                result.add(i + j);
                if (i + j == n) {
                    return result;
                }
            }
        }
        Collections.sort(result);
        return result;
    }

public static int calculateUniqueSum(int[] nums) {
    Set<Integer> set = new HashSet<>(Arrays.asList(nums));
    int sum = 0;
    for (int num : set) {
        sum += num;
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }

    int[] dp = new int[n + 1];
    Arrays.fill(dp, n + 1);

    dp[0] = 0;

    for (int i = 1; i <= n; i++) {
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }

    return dp[n];
}

public static String reverseWords(String s) {
        if (s == null || s.isEmpty()) {
            return "";
        }

        String[] words = s.split(" ");
        StringBuilder reversedSentence = new StringBuilder();

        for (String word : words) {
            StringBuilder reversedWord = new StringBuilder();
            for (int i = word.length() - 1; i >= 0; i--) {
                reversedWord.append(word.charAt(i));
            }
            reversedSentence.append(reversedWord.toString());
            reversedSentence.append(" ");
        }

        // Trim the last space and return the result
        return reversedSentence.toString().replaceAll("( )+", " ").trim();
    }
